INSERT INTO equipment (id, name, category_id, brand, model, price, original_price, stock, level, description, parameters, images, main_image, image_url, suitable_for, features, rating, rating_count, view_count, favorite_count, sales_count, tags, status, is_recommend, create_time, update_time, deleted, hot_score, created_at, updated_at) VALUES (56, '蝴蝶 樊振东 SALC', 1, '蝴蝶', 'FZD SALC', 2980.00, 3280.00, 18, '专业级', '蝴蝶樊振东 SALC 底板，强调高支撑外置速度与近中台连续爆发，适合快攻弧圈体系。', '{"结构": "5木+2SALC", "柄型": "FL", "厚度": "约5.8mm", "重量": "约87g"}', '["/api/upload/equipment/equipment_056_salc.jpg"]', '/api/upload/equipment/equipment_056_salc.jpg', 'https://vsport-tt.com/8543-thickbox_default/blade-butterfly-fan-zhendong-super-alc.jpg', '高水平快攻弧圈, 近中台连续上手', '超级芳碳支撑, 出球直接, 容错稳定', 4.96, 112, 265, 58, 37, '["专业级", "樊振东同系", "超级芳碳"]', 1, 1, NOW(), NOW(), 0, 95, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), category_id=VALUES(category_id), brand=VALUES(brand), model=VALUES(model), price=VALUES(price), original_price=VALUES(original_price), stock=VALUES(stock), level=VALUES(level), description=VALUES(description), parameters=VALUES(parameters), images=VALUES(images), main_image=VALUES(main_image), image_url=VALUES(image_url), suitable_for=VALUES(suitable_for), features=VALUES(features), rating=VALUES(rating), rating_count=VALUES(rating_count), view_count=VALUES(view_count), favorite_count=VALUES(favorite_count), sales_count=VALUES(sales_count), tags=VALUES(tags), status=VALUES(status), is_recommend=VALUES(is_recommend), update_time=NOW(), deleted=0, hot_score=VALUES(hot_score), updated_at=NOW();
