INSERT INTO equipment (id, name, category_id, brand, model, price, original_price, stock, level, description, parameters, images, main_image, image_url, suitable_for, features, rating, rating_count, view_count, favorite_count, sales_count, tags, status, is_recommend, create_time, update_time, deleted, hot_score, created_at, updated_at) VALUES (58, '蝴蝶 Viscaria', 1, '蝴蝶', 'Viscaria', 1680.00, 1880.00, 20, '专业级', '蝴蝶 Viscaria 是经典 ALC 外置底板，速度、旋转和手感平衡，适合高水平弧圈快攻。', '{"结构": "5木+2ALC", "柄型": "FL", "厚度": "约5.8mm", "重量": "约87g"}', '["/api/upload/equipment/equipment_058_viscaria.jpg"]', '/api/upload/equipment/equipment_058_viscaria.jpg', 'https://cdn.store-assets.com/s/713163/i/62526297.jpeg', '弧圈快攻, 中近台对抗, 连续进攻', '经典 ALC 手感, 速度旋转平衡, 上限高', 4.94, 136, 286, 67, 43, '["专业级", "经典 ALC", "张继科同款"]', 1, 1, NOW(), NOW(), 0, 96, NOW(), NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name), category_id=VALUES(category_id), brand=VALUES(brand), model=VALUES(model), price=VALUES(price), original_price=VALUES(original_price), stock=VALUES(stock), level=VALUES(level), description=VALUES(description), parameters=VALUES(parameters), images=VALUES(images), main_image=VALUES(main_image), image_url=VALUES(image_url), suitable_for=VALUES(suitable_for), features=VALUES(features), rating=VALUES(rating), rating_count=VALUES(rating_count), view_count=VALUES(view_count), favorite_count=VALUES(favorite_count), sales_count=VALUES(sales_count), tags=VALUES(tags), status=VALUES(status), is_recommend=VALUES(is_recommend), update_time=NOW(), deleted=0, hot_score=VALUES(hot_score), updated_at=NOW();
